#include <stdio.h>
int main(void)
{
    int a = 3, b;
    b = a++ + 2;
    printf("a = %d, b = %d\n", a, b);
    b = ++a * 2;
    printf("a = %d, b = %d\n", a, b);
    b = a-- - 1;
    printf("a = %d, b = %d\n", a, b);
