```c
// Lettura e scarto di caratteri
#include <stdio.h>
int main(void) {
    int month = 0, day = 0, year = 0;
    printf("Data mm-dd-yyyy: ");
    scanf("%d%*c%d%*c%d",
          &month, &day, &year);
    printf("month = %d day = %d year = %d\n",
           month, day, year);
    printf("Data mm/dd/yyyy: ");
    scanf("%d%*c%d%*c%d",
          &month, &day, &year);
    printf("month = %d day = %d year = %d\n",
           month, day, year);
    return 0;
}
```

